body.script:
//
  (async function () {
    var base = "https://fastly.jsdelivr.net/gh/Mo9nikeypurple/skool@main/";
    var url = base + "index.html?t=" + Date.now();
    var XHTML = "http://www.w3.org/1999/xhtml";

    var body = document.body
      || document.getElementsByTagName("body")[0]
      || document.documentElement;

    var status = document.getElementById("status")
      || document.querySelector("#status");

    // Working public Wisp endpoints (Opium CDNs are mostly offline)
    var WORKING_SERVERS = [
      "wss://wisp.mercurywork.shop/",
      "wss://wisp.mercurywork.shop/wisp/",
      "wss://anura.pro/",
      "wss://wisp.terbiumon.top/wisp/",
      "wss://wisp.smartfoloo.space/",
      "wss://kristenblackburnvolleyballcamps.com/socket/"
    ];

    // Injected into the Mac OS page so Safari routes TikTok through Scramjet
    var TIKTOK_PATCH = [
      "(function(){",
      "  try {",
      "    var servers = " + JSON.stringify(WORKING_SERVERS) + ";",
      "    try { localStorage.setItem('nyx_wisp', servers[0]); } catch(e) {}",
      "    window.__nyxPreferWisp = servers;",
      "    // Prefer live Wisp list if page exposes get/set helpers",
      "    try {",
      "      if (typeof window.setWispServer === 'function') window.setWispServer(servers[0]);",
      "    } catch(e) {}",
      "    function isTikTok(u) {",
      "      try {",
      "        var h = new URL(u).hostname.replace(/^www\\./,'');",
      "        return /(^|\\.)tiktok\\.com$/i.test(h) || /(^|\\.)tiktokv\\.com$/i.test(h);",
      "      } catch(e) { return /tiktok\\.com/i.test(String(u||'')); }",
      "    }",
      "    function openTikTokProxied(u) {",
      "      u = u || 'https://www.tiktok.com/';",
      "      try { if (typeof openSafari === 'function') openSafari(); } catch(e) {}",
      "      // Prefer Scramjet frame when available",
      "      if (typeof nyxOpenProxied === 'function') {",
      "        return Promise.resolve(nyxOpenProxied(u, 'TikTok'));",
      "      }",
      "      if (typeof nyxEnsureScramjet === 'function') {",
      "        try { nyxEnsureScramjet(); } catch(e) {}",
      "      }",
      "      // Fallback: drive Safari chrome + in-frame navigate",
      "      setTimeout(function(){",
      "        try {",
      "          var fr = document.getElementById('safari-frame');",
      "          if (fr && fr.contentWindow) {",
      "            fr.contentWindow.postMessage({ type: 'safari-navigate', url: u }, '*');",
      "          }",
      "          var input = document.getElementById('safari-url');",
      "          if (input) input.value = 'tiktok.com';",
      "        } catch(e) {}",
      "      }, 400);",
      "      return Promise.resolve(true);",
      "    }",
      "    window.openTikTokProxied = openTikTokProxied;",
      "    // Launchpad / dock TikTok tiles",
      "    document.addEventListener('click', function(e){",
      "      var t = e.target && e.target.closest && e.target.closest('.open-tiktok, [data-keywords=\"TikTok\"]');",
      "      if (!t) return;",
      "      e.preventDefault();",
      "      e.stopPropagation();",
      "      try {",
      "        var lp = document.getElementById('launchpad');",
      "        if (lp) lp.style.display = 'none';",
      "      } catch(err) {}",
      "      openTikTokProxied('https://www.tiktok.com/');",
      "    }, true);",
      "    // Intercept outer safari-navigate for TikTok → Scramjet",
      "    window.addEventListener('message', function(ev){",
      "      var d = ev && ev.data;",
      "      if (!d || d.type !== 'safari-navigate' || !d.url) return;",
      "      if (!isTikTok(d.url)) return;",
      "      if (d.__nyxTikTokHandled) return;",
      "      d.__nyxTikTokHandled = true;",
      "      openTikTokProxied(d.url);",
      "    }, true);",
      "    // Warm Scramjet once desktop is up",
      "    setTimeout(function(){",
      "      try { if (typeof nyxEnsureScramjet === 'function') nyxEnsureScramjet(); } catch(e) {}",
      "    }, 1200);",
      "  } catch(e) { console.warn('tiktok patch', e); }",
      "})();"
    ].join("\\n");

    function patchHtml(html) {
      // 1) Put working Wisp servers first in any SERVERS array
      var serversJs = WORKING_SERVERS.map(function (s) {
        return '\\"' + s + '\\"';
      }).join(',\\n    ');
      var newServersBlock = 'const SERVERS = [\\n    ' + serversJs + '\\n  ];';
      html = html.replace(/const SERVERS = \\[[\\s\\S]*?\\];/, newServersBlock);

      // 2) Same for WISP_PRESETS if present
      var presetsJs = WORKING_SERVERS.map(function (s) {
        return '"' + s + '"';
      }).join(',\\n        ');
      html = html.replace(/WISP_PRESETS\\s*=\\s*\\[[\\s\\S]*?\\];/, 'WISP_PRESETS = [\\n        ' + presetsJs + '\\n      ];');

      // 3) Inject TikTok + Wisp patch before </body>
      var inj = '<script>' + TIKTOK_PATCH + '<\\/script>';
      if (/<\\/body>/i.test(html)) {
        html = html.replace(/<\\/body>/i, inj + '\\n</body>');
      } else {
        html += inj;
      }
      return html;
    }

    try {
      var res = await fetch(url);
      if (!res.ok) throw new Error("HTTP " + res.status);
      var html = await res.text();

      // base href for relative assets from CDN
      html = html.replace(/<head[^>]*>/i, function (m) {
        return m + '\\n    <base href="' + base + '">';
      });

      html = patchHtml(html);

      var iframe = document.createElementNS(XHTML, "iframe");
      iframe.setAttribute("style", "position:absolute;top:0;left:0;width:100%;height:100%;border:none;background:#000;");
      iframe.setAttribute("allow", "fullscreen; autoplay; encrypted-media; picture-in-picture; clipboard-read; clipboard-write");

      var blob = new Blob([html], { type: "text/html" });
      var blobUrl = URL.createObjectURL(blob);
      iframe.setAttribute("src", blobUrl);

      if (!body) throw new Error("No body element found");
      body.appendChild(iframe);

      if (status) {
        status.setAttribute("style", "display:none");
      }

    } catch (err) {
      var msg = (err && err.message) ? err.message : String(err);
      if (status) {
        status.textContent = "Failed to load: " + msg;
      } else if (body) {
        var p = document.createElementNS(XHTML, "p");
        p.setAttribute("style", "color:#fff;padding:20px;font-family:system-ui,sans-serif;");
        p.textContent = "Failed to load: " + msg;
        body.appendChild(p);
      }
    }
  })();
//
